import type { ReactNode } from "react";
export function LoadingState({ label = "Loading" }: { label?: string }) { return <div className="state-block" role="status"><div className="mb-4 h-0.5 w-10 bg-[#c97a3e]" /><p className="text-sm font-medium text-[#756d63]">{label}...</p></div>; }
export function EmptyState({ title, message, action }: { title: string; message: string; action?: ReactNode }) { return <div className="state-block"><div className="eyebrow mb-3">Ready when you are</div><h2 className="display-type text-xl font-semibold">{title}</h2><p className="mt-2 max-w-lg text-sm leading-6 text-[#756d63]">{message}</p>{action ? <div className="mt-5 flex">{action}</div> : null}</div>; }
export function ErrorState({ message, onRetry }: { message: string; onRetry?: () => void }) { return <div className="notice notice-error" role="alert"><div className="flex flex-wrap items-center justify-between gap-3"><span>{message}</span>{onRetry ? <button className="button button-secondary" onClick={onRetry}>Try again</button> : null}</div></div>; }
export function SuccessMessage({ message }: { message?: string | null }) { return message ? <div className="notice" role="status">{message}</div> : null; }
