"use client";
import { useCallback, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { EmptyState, ErrorState, LoadingState } from "@/components/data-state";
import { Pagination } from "@/components/pagination";
import { apiRequest } from "@/lib/api-client";
import { formatCurrency } from "@/lib/format";
import type { CatalogueCategory, CatalogueItem, ClientProfile, OrderDetail, PageResponse } from "@/types/api";

export function Procurement() {
  const router = useRouter(); const [categories, setCategories] = useState<CatalogueCategory[] | null>(null); const [items, setItems] = useState<PageResponse<CatalogueItem> | null>(null); const [profile, setProfile] = useState<ClientProfile | null>(null); const [categoryId, setCategoryId] = useState(""); const [page, setPage] = useState(0); const [quantities, setQuantities] = useState<Record<number, number>>({}); const [cartItems, setCartItems] = useState<Record<number, CatalogueItem>>({}); const [deliveryAddress, setDeliveryAddress] = useState(""); const [notes, setNotes] = useState(""); const [error, setError] = useState<string | null>(null); const [submitting, setSubmitting] = useState(false);
  useEffect(() => { Promise.all([apiRequest<CatalogueCategory[]>("catalogue/categories"), apiRequest<ClientProfile>("client/profile")]).then(([categoryData, client]) => { setCategories(categoryData); setProfile(client); setDeliveryAddress(client.deliveryAddress ?? ""); }).catch((caught) => setError(caught instanceof Error ? caught.message : "Catalogue details could not be loaded.")); }, []);
  const loadItems = useCallback(async () => { await Promise.resolve(); setError(null); try { const query = new URLSearchParams({ page: String(page), size: "20" }); if (categoryId) query.set("categoryId", categoryId); setItems(await apiRequest<PageResponse<CatalogueItem>>(`catalogue/items?${query}`)); } catch (caught) { setError(caught instanceof Error ? caught.message : "Catalogue items could not be loaded."); } }, [categoryId, page]);
  useEffect(() => { void Promise.resolve().then(loadItems); }, [loadItems]);
  const selected = useMemo(() => Object.entries(quantities).filter(([, quantity]) => quantity > 0).map(([id, quantity]) => ({ item: cartItems[Number(id)], itemId: Number(id), quantity })).filter((entry): entry is { item: CatalogueItem; itemId: number; quantity: number } => Boolean(entry.item)), [cartItems, quantities]);
  const total = selected.reduce((sum, entry) => sum + entry.item.price * entry.quantity, 0);
  function setQuantity(item: CatalogueItem, value: number) { const quantity = Math.max(0, Math.floor(value || 0)); setQuantities((current) => ({ ...current, [item.id]: quantity })); setCartItems((current) => quantity > 0 ? { ...current, [item.id]: item } : Object.fromEntries(Object.entries(current).filter(([id]) => Number(id) !== item.id))); }
  async function submit() { if (!selected.length || !deliveryAddress.trim()) return; setSubmitting(true); setError(null); try { const order = await apiRequest<OrderDetail>("orders", { method: "POST", body: JSON.stringify({ items: selected.map(({ itemId, quantity }) => ({ itemId, quantity })), deliveryAddress, notes: notes.trim() || null }) }); router.push(`/orders/${encodeURIComponent(order.reference)}?created=1`); } catch (caught) { setError(caught instanceof Error ? caught.message : "The order could not be submitted."); } finally { setSubmitting(false); } }
  if (!categories || !profile || !items) return error ? <ErrorState message={error} onRetry={() => void loadItems()} /> : <LoadingState label="Loading catalogue" />;
  return <div className="grid gap-8 xl:grid-cols-[minmax(0,1fr)_370px]">
    <section aria-labelledby="catalogue-heading" className="min-w-0">
      {error ? <ErrorState message={error} /> : null}
      <div className="flex flex-col gap-4 border-y border-[var(--line-strong)] py-4 sm:flex-row sm:items-end sm:justify-between">
        <div><p className="eyebrow">Available to order</p><h2 id="catalogue-heading" className="display-type mt-1 text-2xl">Catalogue</h2></div>
        <label className="block w-full sm:w-64"><span className="field-label">Filter by category</span><select className="input" value={categoryId} onChange={(event) => { setCategoryId(event.target.value); setPage(0); }}><option value="">All categories</option>{categories.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label>
      </div>
      {items.content.length === 0 ? <div className="mt-5"><EmptyState title="No available items" message="There are no available catalogue items in this category." /></div> : <div>{items.content.map((item) => <article key={item.id} className="catalogue-row grid gap-4 py-5 sm:grid-cols-[minmax(0,1fr)_9rem_8rem] sm:items-center"><div className="min-w-0"><p className="eyebrow">{item.categoryName}</p><h3 className="mt-1 font-semibold text-[var(--forest-deep)]">{item.name}</h3>{item.description ? <p className="mt-1 max-w-2xl text-sm leading-6 text-[var(--muted)]">{item.description}</p> : null}</div><div className="sm:text-right"><div className="font-semibold tabular-nums">{formatCurrency(item.price)}</div><div className="mt-0.5 text-xs text-[var(--muted)]">per {item.unit}</div></div><label className="block"><span className="field-label sm:text-right">Quantity</span><input aria-label={`Quantity for ${item.name}`} className="input text-right tabular-nums" type="number" min="0" step="1" value={quantities[item.id] ?? 0} onChange={(event) => setQuantity(item, Number(event.target.value))} /></label></article>)}</div>}
      <Pagination page={items.page} totalPages={items.totalPages} onChange={setPage} />
    </section>
    <aside className="xl:sticky xl:top-24 xl:self-start">
      <div className="border-t-2 border-[var(--forest)] bg-[var(--paper)] shadow-[0_12px_32px_rgba(42,42,42,0.07)]">
        <div className="border-b border-[var(--line)] p-5"><p className="eyebrow">Draft order</p><div className="mt-1 flex items-baseline justify-between gap-3"><h2 className="display-type text-2xl">Order review</h2><span className="text-xs font-semibold text-[var(--muted)]">{selected.length} {selected.length === 1 ? "item" : "items"}</span></div></div>
        <div className="p-5">{selected.length ? <div>{selected.map(({ item, quantity }) => <div key={item.id} className="grid grid-cols-[1fr_auto] gap-3 border-b border-[var(--line)] py-3 first:pt-0"><div><div className="text-sm font-semibold">{item.name}</div><div className="mt-1 text-xs text-[var(--muted)]">{quantity} × {formatCurrency(item.price)}</div></div><div className="text-sm font-semibold tabular-nums">{formatCurrency(item.price * quantity)}</div></div>)}<div className="mt-4 flex items-end justify-between gap-3"><span className="text-sm font-semibold">Estimated total</span><span className="display-type text-2xl text-[var(--forest-deep)]">{formatCurrency(total)}</span></div><p className="mt-2 text-xs leading-5 text-[var(--muted)]">Prices and the final total are verified when the order is submitted.</p></div> : <div className="py-3"><p className="font-semibold">Your order is empty</p><p className="mt-1 text-sm leading-6 text-[var(--muted)]">Enter a quantity beside an item to add it here.</p></div>}
          <div className="mt-5 space-y-4 border-t border-[var(--line-strong)] pt-5"><label className="block"><span className="field-label">Delivery address</span><textarea className="input min-h-24 resize-y" value={deliveryAddress} onChange={(event) => setDeliveryAddress(event.target.value)} maxLength={500} required /></label><label className="block"><span className="field-label">Order note <span className="font-normal text-[var(--muted)]">(optional)</span></span><textarea className="input min-h-20 resize-y" value={notes} onChange={(event) => setNotes(event.target.value)} maxLength={1000} /></label><button className="button button-primary w-full" disabled={!selected.length || !deliveryAddress.trim() || submitting} onClick={() => void submit()}>{submitting ? "Submitting order..." : "Submit order"}</button></div>
        </div>
      </div>
    </aside>
  </div>;
}
