import type { ApiError } from "@/types/api";
export class ApiRequestError extends Error { constructor(message: string, public readonly status: number, public readonly code?: string, public readonly errors?: Record<string, string>) { super(message); } }
export async function apiRequest<T>(path: string, init?: RequestInit): Promise<T> { const response = await fetch(`/api/client/${path.replace(/^\//, "")}`, { ...init, headers: { ...(init?.body ? { "Content-Type": "application/json" } : {}), ...init?.headers }, cache: "no-store" }); if (response.status === 401) { window.location.replace("/login"); throw new ApiRequestError("Your session has expired.", 401, "UNAUTHENTICATED"); } const data = (await response.json().catch(() => null)) as T | ApiError | null; if (!response.ok) { const error = data as ApiError | null; throw new ApiRequestError(error?.message ?? "The request could not be completed.", response.status, error?.code, error?.errors); } return data as T; }
